Inductive sigX2 (T1 T2 : Type) (P : T1 -> T2 -> Prop) : Prop := mkSigX2 : forall (x : T1) (x0 : T2), P x x0 -> sigX2 T1 T2 P.
Lemma to_sigX2 : forall (T1 T2 : Type) (P : T1 -> T2 -> Prop), (exists y1 y2, P y1 y2) -> sigX2 T1 T2 P.
Proof. intros T1 T2 P [y1 [y2 H]]. exact (mkSigX2 T1 T2 P y1 y2 H). Qed.
Inductive sigX3 (T1 T2 T3 : Type) (P : T1 -> T2 -> T3 -> Prop) : Prop := mkSigX3 : forall (x : T1) (x0 : T2) (x1 : T3), P x x0 x1 -> sigX3 T1 T2 T3 P.
Lemma to_sigX3 : forall (T1 T2 T3 : Type) (P : T1 -> T2 -> T3 -> Prop), (exists y1 y2 y3, P y1 y2 y3) -> sigX3 T1 T2 T3 P.
Proof. intros T1 T2 T3 P [y1 H]. destruct (to_sigX2 T2 T3 (P y1) H) as [y2 y3 H2]. exact (mkSigX3 T1 T2 T3 P y1 y2 y3 H2). Qed.
